.candidate-live-summary{display:grid;grid-template-columns:auto auto;align-items:center;gap:.1rem .65rem;padding:.5rem .75rem;border:1px solid #fecaca;border-radius:11px;background:#fff7f7}.candidate-live-summary>span{grid-row:1/3;font-size:.68rem;font-weight:900;color:#dc2626;text-transform:uppercase}.candidate-live-summary strong{font-size:.76rem;color:#1e293b}.candidate-live-summary small{font-size:.65rem;color:#64748b}.package-live-result{margin:0 1rem 1rem;padding:.85rem 1rem;border:1px solid #bfdbfe;border-radius:13px;background:linear-gradient(145deg,#eff6ff,#f0fdfa)}.package-live-result__head{display:flex;justify-content:space-between;align-items:center;margin-bottom:.65rem}.package-live-result__head>span{font-size:.7rem;font-weight:900;color:#dc2626;text-transform:uppercase}.package-live-result .live-package-value{display:flex;align-items:baseline;gap:.4rem}.package-live-result .live-package-value strong{font-size:1.2rem}.package-live-result .live-bar{height:12px}.package-live-result>small{display:block;margin-top:.45rem;color:#64748b;font-size:.66rem}
.live-polling{padding:1.25rem;border:1px solid #bfdbfe;border-radius:17px;background:linear-gradient(145deg,#eff6ff,#fff 58%,#ecfdf5);box-shadow:0 14px 32px rgba(37,99,235,.09)}
.live-polling__head{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.live-polling__head small{font-weight:900;color:#dc2626;letter-spacing:.08em}.live-polling__head h2{font-size:1.15rem;font-weight:900;color:#0f172a;margin:.2rem 0}.live-polling__head p{color:#64748b;margin:0}.live-dot{display:inline-block;width:9px;height:9px;margin-right:.45rem;border-radius:50%;background:#ef4444;box-shadow:0 0 0 0 rgba(239,68,68,.5);animation:livePulse 1.6s infinite}.live-polling__time{display:grid;grid-template-columns:auto auto;align-items:center;gap:.05rem .45rem;padding:.65rem .85rem;border:1px solid #dbeafe;border-radius:11px;background:rgba(255,255,255,.8)}.live-polling__time i{grid-row:1/3;color:#2563eb}.live-polling__time span{font-size:.65rem;color:#94a3b8}.live-polling__time strong{font-size:.85rem;color:#1e293b}.live-polling__metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem;margin:1rem 0}.live-polling__metrics div{padding:.75rem 1rem;border:1px solid #e2e8f0;border-radius:11px;background:#fff}.live-polling__metrics span{display:block;font-size:.68rem;font-weight:800;color:#64748b;text-transform:uppercase}.live-polling__metrics strong{font-size:1.35rem;color:#1d4ed8}.live-polling__packages{display:grid;gap:.7rem}.live-polling__packages article{display:grid;grid-template-columns:180px 1fr 90px;align-items:center;gap:1rem;padding:.7rem .85rem;border-radius:11px;background:#fff}.live-package-label span,.live-package-label strong,.live-package-value span,.live-package-value strong{display:block}.live-package-label span{font-size:.65rem;font-weight:800;color:#2563eb}.live-package-label strong{color:#1e293b}.live-bar{height:15px;overflow:hidden;border-radius:999px;background:#e2e8f0}.live-bar span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#2563eb,#14b8a6);transition:width .45s ease}.live-package-value{text-align:right}.live-package-value strong{color:#0f172a;font-size:1.05rem}.live-package-value span{color:#64748b;font-size:.72rem}@keyframes livePulse{70%{box-shadow:0 0 0 8px rgba(239,68,68,0)}100%{box-shadow:0 0 0 0 rgba(239,68,68,0)}}
.candidate-assignment{padding:1rem;margin-bottom:1rem;border:1px solid #dbeafe;border-radius:15px;background:#f8fbff}.candidate-assignment__head{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem}.candidate-assignment__head span{font-size:.65rem;font-weight:900;color:#2563eb;letter-spacing:.08em}.candidate-assignment__head h6{font-size:1rem;font-weight:900;color:#0f172a;margin:.15rem 0}.candidate-assignment__head p{font-size:.78rem;color:#64748b;margin:0}.candidate-assignment__head>i{font-size:2rem;color:#93c5fd}.candidate-role-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.candidate-role{padding:.8rem;text-align:center;border:1px solid #dbe4f0;border-radius:14px;background:#fff}.candidate-role__photo{display:grid;place-items:center;width:82px;height:100px;margin:0 auto .55rem;overflow:hidden;border-radius:14px;background:linear-gradient(145deg,#eff6ff,#e0f2fe);color:#60a5fa;font-size:1.6rem}.candidate-role__photo img{width:100%;height:100%;object-fit:cover}.candidate-role>span,.candidate-role>strong,.candidate-role>small{display:block}.candidate-role>span{font-size:.65rem;font-weight:900;color:#2563eb;text-transform:uppercase}.candidate-role>strong{margin:.2rem 0;color:#0f172a}.candidate-role>small{min-height:18px;color:#64748b}.candidate-role .btn{margin-top:.55rem;border-radius:9px}.candidate-browser{margin-top:1rem;padding:1rem;border-radius:14px;background:#0f172a}.candidate-browser__toolbar{display:flex;align-items:center;gap:.8rem}.candidate-browser__toolbar>div:first-child{min-width:110px}.candidate-browser__toolbar small,.candidate-browser__toolbar strong{display:block}.candidate-browser__toolbar small{font-size:.6rem;color:#60a5fa;font-weight:900}.candidate-browser__toolbar strong{color:#fff}.candidate-search{position:relative;flex:1}.candidate-search i{position:absolute;left:12px;top:11px;color:#94a3b8}.candidate-search input{width:100%;height:38px;padding:0 12px 0 35px;border:0;border-radius:9px;background:#fff}.candidate-browser__status{padding:.7rem 0;color:#94a3b8;font-size:.75rem}.candidate-browser__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.55rem;max-height:360px;overflow:auto;padding-right:.2rem}.candidate-option{display:grid;grid-template-columns:58px minmax(0,1fr);align-items:center;gap:.65rem;padding:.5rem;border:1px solid #334155;border-radius:11px;background:#1e293b;color:#fff;text-align:left;cursor:pointer;transition:.18s}.candidate-option:hover{transform:translateY(-1px);border-color:#60a5fa;background:#243550}.candidate-option img{width:58px;height:72px;object-fit:cover;border-radius:8px}.candidate-option__body{min-width:0}.candidate-option strong,.candidate-option span{display:block}.candidate-option strong{font-size:.75rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.candidate-option span{margin-top:.2rem;font-size:.65rem;color:#94a3b8}.candidate-option-loading{grid-column:1/-1;padding:.75rem;text-align:center;color:#94a3b8;font-size:.74rem}
.candidate-role-grid{grid-template-columns:repeat(var(--role-columns,2),1fr)}
@media(max-width:991.98px){.candidate-browser__grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767.98px){.live-polling__head{flex-direction:column}.live-polling__time{width:100%}.live-polling__packages article{grid-template-columns:1fr}.live-package-value{text-align:left}.candidate-role-grid{grid-template-columns:1fr}.candidate-browser__toolbar{align-items:stretch;flex-wrap:wrap}.candidate-search{flex-basis:100%}.candidate-browser__grid{grid-template-columns:1fr}}
</style>
<style>
.package-campaign-photo{aspect-ratio:16/7;margin:1rem;overflow:hidden;border:1px solid #dbeafe;border-radius:14px;background:linear-gradient(135deg,#eff6ff,#f0fdfa);box-shadow:0 10px 24px rgba(15,23,42,.08)}.package-campaign-photo img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 32%}@media(max-width:767.98px){.package-campaign-photo{aspect-ratio:4/3;margin:.8rem}.package-campaign-photo img{object-position:center 25%}}
</style>
