@section('js')
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const photoControls=document.createElement('div');photoControls.className='row package-photo-controls';photoControls.innerHTML='<div class="col-md-6 form-group"><label><i class="fas fa-image text-primary mr-1"></i>Foto Bersama Kandidat</label><label class="btn btn-sm btn-outline-primary d-block text-left mb-1" for="campaignPhotoInput"><i class="fas fa-upload mr-1"></i>Unggah foto utama</label><small class="text-muted d-block" id="campaignPhotoHint">Foto utama paket dan fallback ketika foto profil kandidat tidak tersedia.</small></div><div class="col-md-6 form-group"><label><i class="fas fa-images text-primary mr-1"></i>Galeri Live Polling</label><label class="btn btn-sm btn-outline-primary d-block text-left mb-1" for="livePhotosInput"><i class="fas fa-images mr-1"></i>Unggah hingga 6 foto</label><small class="text-muted d-block" id="livePhotosHint">Foto akan bergantian otomatis di layar live. Upload baru menggantikan galeri sebelumnya.</small></div>';
document.querySelector('#packageForm .candidate-assignment').before(photoControls);
document.getElementById('campaignPhotoInput').addEventListener('change',function(){document.getElementById('campaignPhotoHint').textContent=this.files[0]?'Foto dipilih: '+this.files[0].name:'Foto utama paket dan fallback ketika foto profil kandidat tidak tersedia.'});
document.getElementById('livePhotosInput').addEventListener('change',function(){document.getElementById('livePhotosHint').textContent=this.files.length?this.files.length+' foto siap diunggah; galeri lama akan diganti.':'Foto akan bergantian otomatis di layar live. Upload baru menggantikan galeri sebelumnya.'});
const packages=@json($packageData);
const voterMonitor=document.getElementById('voterMonitor');
if(voterMonitor){let voterPage=1,voterLast=1,voterTimer;const csrf=document.querySelector('meta[name="csrf-token"]')?.content;const esc=value=>$('<div>').text(value??'').html();const loadVoters=async()=>{const p=new URLSearchParams({page:voterPage,type:$('#voterType').val(),tingkat:$('#voterLevel').val(),kelas_id:$('#voterClass').val(),search:$('#voterSearch').val().trim(),status:voterMonitor.dataset.status||''});const r=await fetch(voterMonitor.dataset.url+'?'+p,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();voterLast=d.pagination.last;$('#voterTotal').text(Number(d.pagination.total).toLocaleString('id-ID')+' pemilih');$('#voterPage').text('Halaman '+d.pagination.page+' dari '+d.pagination.last);$('#voterPrev').prop('disabled',voterPage<=1);$('#voterNext').prop('disabled',voterPage>=voterLast);$('#voterRows').html(d.rows.length?d.rows.map(v=>`<tr><td><strong>${esc(v.name)}</strong><div class="small text-muted">${esc(v.identity||'-')} · ${v.type==='student'?'Siswa':'GTK'}</div></td><td>${esc(v.scope)}</td><td>${v.voted?'<span class="badge badge-success"><i class="fas fa-lock mr-1"></i>Sudah memilih</span>':'<span class="badge badge-warning">Belum memilih</span>'}</td><td>${esc(v.voted_at||'-')}</td><td class="text-right">${v.can_unlock?`<button class="btn btn-sm btn-outline-warning unlock-voter" data-id="${v.id}" data-name="${esc(v.name)}"><i class="fas fa-unlock-alt"></i> Unlock</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="text-center text-muted py-3">Tidak ada pemilih sesuai filter.</td></tr>')};$('#voterType,#voterLevel,#voterClass').on('change',function(){if(this.id==='voterLevel')$('#voterClass option').each(function(){$(this).toggle(!this.dataset.level||this.dataset.level===this.value)});voterPage=1;loadVoters()});$('#voterSearch').on('input',()=>{clearTimeout(voterTimer);voterTimer=setTimeout(()=>{voterPage=1;loadVoters()},300)});$('#voterPrev').on('click',()=>{if(voterPage>1){voterPage--;loadVoters()}});$('#voterNext').on('click',()=>{if(voterPage<voterLast){voterPage++;loadVoters()}});$(document).on('click','.detail-stat-link',function(){voterMonitor.dataset.status=this.dataset.voterStatus==='all'?'':this.dataset.voterStatus;voterPage=1;document.getElementById('voterMonitor').scrollIntoView({behavior:'smooth',block:'start'});loadVoters()});$(document).on('click','.unlock-voter',function(){const b=this;Swal.fire({icon:'warning',title:'Unlock hak pilih?',text:b.dataset.name+' harus memilih ulang. Suara sebelumnya akan dibatalkan.',showCancelButton:true,confirmButtonText:'Ya, unlock',cancelButtonText:'Batal'}).then(async x=>{if(!x.isConfirmed)return;const r=await fetch(voterMonitor.dataset.unlockTemplate.replace('__VOTER__',b.dataset.id),{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'}}),d=await r.json();if(!r.ok)return Swal.fire('Belum dapat diproses',d.message,'error');Swal.fire('Berhasil',d.message,'success');loadVoters()})});loadVoters()}
const packageStoreUrl=@json(route('admin.osis-election.packages.store',$election));
const candidateUrl=@json(route('admin.osis-election.candidates',$election));
const candidateFields=@json(collect($roleDefinitions)->pluck('field')->values());
const candidatesLocked=@json($election->status==='paused');
let activeCandidateField=null,candidateSearchTimer=null,candidateRequest=null,visibleCandidates={},candidatePage=1,candidateHasMore=false,candidateLoading=false,candidateSearchValue='';
function escapeHtml(value){return $('<div>').text(value??'').html()}
function selectedCandidateIds(exceptField=null){const f=document.getElementById('packageForm');return candidateFields.filter(k=>k!==exceptField&&f.elements[k].value).map(k=>f.elements[k].value)}
function renderCandidateRole(field,student=null){const card=document.querySelector(`.candidate-role[data-field="${field}"]`),input=document.getElementById('packageForm').elements[field],img=card.querySelector('img'),icon=card.querySelector('.candidate-role__photo i'),button=card.querySelector('button');input.value=student?.id||'';card.querySelector('strong').textContent=student?.name||'Belum dipilih';card.querySelector('small').textContent=student?`${student.class} · NISN ${student.nisn||'-'}`:'Klik untuk memilih siswa';if(student){img.src=student.photo;img.alt=student.name;img.hidden=false;icon.hidden=true}else{img.hidden=true;img.removeAttribute('src');icon.hidden=false}button.innerHTML=candidatesLocked?'<i class="fas fa-lock mr-1"></i>Terkunci':(student?'<i class="fas fa-exchange-alt mr-1"></i>Ganti ':'<i class="fas fa-search mr-1"></i>Pilih ')+card.querySelector('span').textContent}
function resetCandidateRoles(){candidateFields.forEach(field=>renderCandidateRole(field));document.getElementById('candidateBrowser').hidden=true;document.getElementById('candidateSearch').value='';visibleCandidates={};candidatePage=1;candidateHasMore=false;candidateLoading=false;candidateSearchValue=''}
function candidateOptionMarkup(student){return `<button type="button" class="candidate-option" data-student-id="${escapeHtml(student.id)}"><img src="${escapeHtml(student.photo)}" alt="${escapeHtml(student.name)}" loading="lazy"><div class="candidate-option__body"><strong>${escapeHtml(student.name)}</strong><span>${escapeHtml(student.class)} · NISN ${escapeHtml(student.nisn||'-')}</span></div></button>`}
async function loadCandidates(search='',append=false){if(!activeCandidateField||(append&&(candidateLoading||!candidateHasMore)))return;const status=document.getElementById('candidateBrowserStatus'),grid=document.getElementById('candidateBrowserGrid');if(!append){if(candidateRequest)candidateRequest.abort();candidatePage=1;candidateHasMore=false;candidateSearchValue=search;visibleCandidates={};grid.innerHTML='';status.textContent='Memuat siswa yang tersedia...'}candidateLoading=true;const request=new AbortController();candidateRequest=request;const requestedPage=append?candidatePage+1:1;const params=new URLSearchParams({search:candidateSearchValue,current_package_id:document.getElementById('currentPackageId').value,page:requestedPage});selectedCandidateIds(activeCandidateField).forEach(id=>params.append('exclude_ids[]',id));if(append)grid.insertAdjacentHTML('beforeend','<div class="candidate-option-loading"><i class="fas fa-circle-notch fa-spin mr-1"></i>Memuat siswa berikutnya...</div>');try{const response=await fetch(candidateUrl+'?'+params.toString(),{headers:{Accept:'application/json'},signal:request.signal});if(!response.ok)throw new Error('Gagal memuat kandidat');const data=await response.json();grid.querySelector('.candidate-option-loading')?.remove();data.students.forEach(student=>visibleCandidates[student.id]=student);grid.insertAdjacentHTML('beforeend',data.students.map(candidateOptionMarkup).join(''));candidatePage=data.pagination.page;candidateHasMore=data.pagination.has_more;status.textContent=data.pagination.total?`${Object.keys(visibleCandidates).length} dari ${data.pagination.total} siswa ditampilkan${candidateHasMore?' · gulir ke bawah untuk memuat lagi':''} · siswa yang sudah dipakai disembunyikan`:'Tidak ada siswa yang sesuai.'}catch(error){grid.querySelector('.candidate-option-loading')?.remove();if(error.name!=='AbortError')status.textContent='Data kandidat gagal dimuat. Silakan coba lagi.'}finally{if(candidateRequest===request)candidateLoading=false}}
$(document).on('click','.btn-open-candidate',function(){if(candidatesLocked)return;activeCandidateField=this.dataset.field;document.getElementById('candidateRoleLabel').textContent=this.dataset.label;document.getElementById('candidateBrowser').hidden=false;document.getElementById('candidateSearch').value='';loadCandidates();setTimeout(()=>document.getElementById('candidateSearch').focus(),100)});
$(document).on('click','.candidate-option',function(){renderCandidateRole(activeCandidateField,visibleCandidates[this.dataset.studentId]);document.getElementById('candidateBrowser').hidden=true;activeCandidateField=null});
$('#candidateSearch').on('input',function(){clearTimeout(candidateSearchTimer);candidateSearchTimer=setTimeout(()=>loadCandidates(this.value.trim()),300)});
$('#candidateBrowserGrid').on('scroll',function(){if(this.scrollTop+this.clientHeight>=this.scrollHeight-90)loadCandidates(candidateSearchValue,true)});
$('#closeCandidateBrowser').on('click',function(){document.getElementById('candidateBrowser').hidden=true;activeCandidateField=null});
$('[data-target="#packageModal"]').on('click',function(){const f=document.getElementById('packageForm');f.reset();f.action=packageStoreUrl;$('#packageMethod').val('POST');$('#currentPackageId').val('');$('.modal-title').text('Tambah Paket');resetCandidateRoles()});
$('.btn-edit-package').on('click',function(){const id=$(this).data('id'),p=packages[id],f=document.getElementById('packageForm');f.reset();f.action=p.url;$('#packageMethod').val('PUT');$('#currentPackageId').val(id);$('.modal-title').text('Edit Paket '+p.number);['number','name','slogan','vision','mission','programs','message'].forEach(k=>f.elements[k].value=p[k]??'');document.getElementById('campaignPhotoHint').textContent=p.campaignPhoto?'Foto utama sudah tersedia. Unggah file baru untuk mengganti.':'Belum ada foto utama; gunakan foto bersama sebagai fallback.';document.getElementById('livePhotosHint').textContent=p.livePhotos?.length?p.livePhotos.length+' foto live tersedia. Upload baru akan menggantikannya.':'Belum ada galeri live.';candidateFields.forEach(k=>renderCandidateRole(k,p.candidates[k]));document.getElementById('candidateBrowser').hidden=true;$('#packageModal').modal('show')});
$('.confirm-form').on('submit',function(e){e.preventDefault();const f=this;Swal.fire({icon:'question',title:'Konfirmasi',text:f.dataset.confirm,showCancelButton:true,confirmButtonText:'Ya, lanjutkan',cancelButtonText:'Batal',confirmButtonColor:'#2563eb'}).then(r=>{if(r.isConfirmed)f.submit()})});
$('#voterLevel').on('change',function(){const level=$(this).val();$('#voterClass option').each(function(){$(this).toggle(!this.dataset.level||this.dataset.level===level)});$('#voterClass').val('')});
const livePolling=document.getElementById('livePolling');if(livePolling){const refreshLivePolling=async()=>{const icon=document.getElementById('livePollingIcon');icon.classList.add('fa-spin');try{const response=await fetch(livePolling.dataset.url,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();document.getElementById('liveVoted').textContent=Number(data.voted).toLocaleString('id-ID');document.getElementById('liveRemaining').textContent=Number(data.remaining).toLocaleString('id-ID');document.getElementById('liveTurnout').textContent=data.turnout+'%';document.getElementById('livePollingTime').textContent=data.updated_at;data.packages.forEach(item=>{const row=document.querySelector(`[data-package-id="${item.id}"]`);if(!row)return;row.querySelector('.live-bar span').style.width=item.percentage+'%';row.querySelector('.live-package-value strong').textContent=Number(item.votes).toLocaleString('id-ID');row.querySelector('.live-package-value span').textContent=item.percentage+'%'})}finally{icon.classList.remove('fa-spin')}};setInterval(()=>{if(!document.hidden)refreshLivePolling()},3000)}
@if(session('success'))Swal.fire({icon:'success',title:'Berhasil',text:@json(session('success')),confirmButtonColor:'#2563eb'});@endif
@if(session('error'))Swal.fire({icon:'error',title:'Belum dapat diproses',text:@json(session('error')),confirmButtonColor:'#2563eb'});@endif
@if($errors->any())Swal.fire({icon:'error',title:'Periksa isian',html:@json(implode('<br>',$errors->all())),confirmButtonColor:'#2563eb'}).then(()=>$('#packageModal').modal('show'));@endif
</script>
@stop
